#!/usr/bin/env python3
import types,sys,json,os,csv,sqlite3,zlib,zipfile
from pathlib import Path
stream=types.ModuleType("research_stream_artifact")
previous=sys.modules.get("research_stream_artifact")
sys.modules["research_stream_artifact"]=stream
design=types.ModuleType("research_design");old_design=sys.modules.get("research_design");sys.modules["research_design"]=design
component=types.ModuleType("c_network_source");component._EMBEDDED_SOURCE_IDS={'component_sha256': 'cdcef5349d1a6e7abcb6160f67f0ddc29347ef9abe2137f15944bb4d0b2eb05a', 'stream_support_sha256': '0b5d218f7120dc897d2daa0acb801a95527e70e61fd58fd1a4788761c0189b13', 'design_reader_sha256': 'f18399f81180d8d3637b03eb5f4a7369b5a05a6e31909d50375538006d329f14'}
try:
    exec(compile(bytes.fromhex(""),"bundled-stream-support","exec"),stream.__dict__)
    exec(compile(bytes.fromhex(""),"bundled-design-reader","exec"),design.__dict__)
    exec(compile(bytes.fromhex(""),"bundled-c-network-source","exec"),component.__dict__)
finally:
    if previous is None:sys.modules.pop("research_stream_artifact",None)
    else:sys.modules["research_stream_artifact"]=previous
    if old_design is None:sys.modules.pop("research_design",None)
    else:sys.modules["research_design"]=old_design

def run():
    inputs = [Path(os.environ['AUTONOMICS_INPUT'+str(i)]) for i in range(6)]
    outputs = [Path(os.environ['AUTONOMICS_OUTPUT'+str(i)]) for i in range(3)]
    component.require([p.name for p in outputs] ==
        ['network-edges.tsv', 'network-nodes.tsv', 'source-audit.json'], 'exact source output ports required')
    parent = outputs[0].parent.absolute()
    component.require(len({p.parent.absolute() for p in outputs}) == 1 and parent != Path('/') and
        all(p.is_absolute() and '..' not in p.parts for p in outputs), 'private absolute source ports required')
    component.require(not any(os.path.lexists(p) for p in outputs) and
        not any(p.is_symlink() for p in [parent, *parent.parents]), 'existing or symlink source output refused')
    with stream.regular_open(inputs[0]) as f:
        raw = f.read(stream.META_LIMIT+1)
    component.require(0 < len(raw) <= stream.META_LIMIT, 'complete bounded source declaration required')
    actual = stream.apply_process_memory_limit(component.strict(raw)['source_io'])
    parent.mkdir(parents=True, exist_ok=True)
    bundle = parent / '.c-network-source-complete'
    component.require(not os.path.lexists(bundle), 'complete source bundle exists')
    audit = component.normalize(inputs[0], dict(zip(component.INPUTS, inputs[1:])), bundle)
    # Ports link from the complete content-verified bundle. A linking failure
    # fails the node; the real engine must publish no normal outputs on failure.
    for target in outputs:
        os.link(bundle/target.name, target)
    print(json.dumps({'status': audit['status'], 'actual_source_RLIMIT_AS_bytes': actual,
        'counts': audit['counts'], 'formal_authorized': False}))
if __name__ == '__main__':
    try:
        run()
    except (ValueError, KeyError, TypeError, OSError, UnicodeError, csv.Error,
            sqlite3.Error, EOFError, MemoryError, zlib.error, zipfile.BadZipFile) as e:
        print('BLOCKED: '+str(e), file=sys.stderr)
        raise SystemExit(2)
